window.MG_LAZY_DATA["data/lazy/resources/security-v26-029-c0a33e63c5c1787e.json"]={sha256:"c0a33e63c5c1787ea601a374c6917040c423f8bd8830e6edcace4f153ca4f6d2",value:{"sources":[{"id":"v26-case-0b3484edabc80964","url":"https://docs.zeek.org/en/current/reference/logs/index.html","title":"Zeek: Common Logs","titleEn":"Zeek: Common Logs","publisher":"Zeek Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-029","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-029","related":[{"id":"security-v26-030","referenceUrls":["https://docs.suricata.io/en/suricata-8.0.2/output/eve/eve-json-output.html"],"title":"Suricata EVE：警報、流量與感測器損失","titleEn":"Suricata EVE: alerts, flows and sensor loss","why":"用兩課的可觀察驗收條件比較模型邊界：84%與94%由唯一關聯重算，多對多不強制選一；未把TLS metadata當作已解密應用內容。 交付三表關聯圖、500事件品質報告與未配對清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 84% and 94% from unique joins, preserve many-to-many ambiguity and do not present TLS metadata as decrypted application content. Deliver a three-table join diagram, 500-event quality report and unmatched-event list.","difference":"以合成EVE行分開event_type、flow_id、timestamp、sensor與alert action；建立警報到流量的可追溯關係，保留stats損失證據。","differenceEn":"Separate event_type, flow_id, timestamp, sensor and alert action in synthetic EVE lines; trace alerts to flows and retain sensor-loss statistics.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["可關聯率=具有必要共同鍵且可唯一連結的事件/總事件；共享IP與快取DNS會使名稱推論不唯一。 合成500個TLS事件中，420個有可唯一關聯的conn uid，80個缺失或重複。 420/500×100=84%；修正50個後470/500×100=94%。","輸入位元組率=事件率×平均序列化大小；有警報不等於已封鎖，alert action與實際處置需分開理解。 教學感測器每秒2000事件，平均每事件750位元組；不含傳輸、索引與副本開銷。 2000×750=1500000位元組/秒；事件率增至3000時為2250000位元組/秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Joinability is events with required keys and a unique join divided by all events; shared IPs and cached DNS can make name inference ambiguous. Of 500 synthetic TLS events, 420 uniquely join to a connection uid and 80 are missing or duplicated. 420/500×100=84%; repairing 50 gives 470/500×100=94%.","Ingest byte rate is event rate×average serialized size; an alert does not prove blocking, and alert action must be interpreted separately from actual enforcement. A teaching sensor emits 2000 events/s averaging 750 bytes, excluding transport, indexing and replication overhead. 2000×750=1500000 bytes/s; 3000 events/s requires 2250000 bytes/s.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-039","referenceUrls":["https://yara.readthedocs.io/en/stable/writingrules.html"],"title":"YARA：無害標記、字串條件與反例設計","titleEn":"YARA: inert markers, string conditions and negative fixtures","why":"用兩課的可觀察驗收條件比較模型邊界：84%與94%由唯一關聯重算，多對多不強制選一；未把TLS metadata當作已解密應用內容。 交付三表關聯圖、500事件品質報告與未配對清單。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 84% and 94% from unique joins, preserve many-to-many ambiguity and do not present TLS metadata as decrypted application content. Deliver a three-table join diagram, 500-event quality report and unmatched-event list.","difference":"僅建立含ALPHA、BETA、GAMMA三個無害標記的文字fixture；對「至少兩個標記」列完整存在/不存在真值表，另外測空檔與文字編碼。","differenceEn":"Create text fixtures containing harmless ALPHA, BETA and GAMMA markers; enumerate presence/absence truth tables for at least two markers and separately test empty files and encoding.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["可關聯率=具有必要共同鍵且可唯一連結的事件/總事件；共享IP與快取DNS會使名稱推論不唯一。 合成500個TLS事件中，420個有可唯一關聯的conn uid，80個缺失或重複。 420/500×100=84%；修正50個後470/500×100=94%。","m個獨立布林標記有2^m種組合；存在性邏輯、字串邊界與編碼需分別驗證，樣本不可包含可執行惡意內容。 基準有3個標記，每個只計有/無，組合無其他限制。 2^3=8組；加入DELTA後2^4=16組。對至少兩標記條件，三標記版應有4組命中。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Joinability is events with required keys and a unique join divided by all events; shared IPs and cached DNS can make name inference ambiguous. Of 500 synthetic TLS events, 420 uniquely join to a connection uid and 80 are missing or duplicated. 420/500×100=84%; repairing 50 gives 470/500×100=94%.","m independent Boolean markers give 2^m combinations; test existence logic, word boundaries and encoding separately using no executable malicious content. Baseline has three markers, each present or absent with no other constraints. 2^3=8 combinations; adding DELTA gives 2^4=16. At least two of three should match four combinations.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-3d0919c53260f599","url":"https://docs.suricata.io/en/suricata-8.0.2/output/eve/eve-json-output.html","title":"Suricata 8.0.2 EVE JSON output","titleEn":"Suricata 8.0.2 EVE JSON output","publisher":"OISF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-8b282b9c60ccf648","url":"https://yara.readthedocs.io/en/stable/writingrules.html","title":"YARA: Writing rules","titleEn":"YARA: Writing rules","publisher":"YARA Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
